diff --git a/CHANGELOG.md b/CHANGELOG.md
index e010a34bf5..3382505bea 100644
--- a/CHANGELOG.md
+++ b/CHANGELOG.md
@@ -13,6 +13,18 @@ block a release again.

 ## Unreleased

+- fix(gh-2140): the Flutter app boots on Windows desktop. The unguarded
+  `DefaultFirebaseOptions.currentPlatform` read in `_initFirebaseApp`
+  threw `Unsupported operation` on platforms with no Firebase
+  registration (the template options register only android/ios/web/macos
+  — Windows/Linux throw before the `YOUR_` placeholder check could run),
+  killing boot before the first frame: the boot-watchdog fired and no
+  window ever opened. The read is now guarded — Firebase is
+  telemetry-only, so the services stage degrades with a debug print and
+  the app boots without it. Test: `bootServices degrades on platforms
+  with no Firebase registration` (windows-target override; previously
+  threw, now completes).
+
 - feat(gh-2098): the auto-compact trigger is user-configurable —
   `compaction.triggerRatio` / `compaction.reserveTokens` /
   `compaction.keepRecentTokens` in `~/.fah/config.yaml` or project
diff --git a/flutter_app/lib/boot/app_boot.dart b/flutter_app/lib/boot/app_boot.dart
index 83c051488a..ef696a2a69 100644
--- a/flutter_app/lib/boot/app_boot.dart
+++ b/flutter_app/lib/boot/app_boot.dart
@@ -419,7 +419,19 @@ void _teeDebugPrintIntoAppLog() {
 /// before the first frame (black screen on macOS/iOS). Reuse the natively
 /// configured app in that case.
 Future<void> _initFirebaseApp() async {
-  final options = DefaultFirebaseOptions.currentPlatform;
+  final FirebaseOptions options;
+  try {
+    options = DefaultFirebaseOptions.currentPlatform;
+  } on Object catch (error) {
+    // Platforms with no Firebase registration (Windows/Linux desktop with
+    // the template options — issue: Windows boot died before the first
+    // frame) throw from the generated switch before the placeholder check
+    // below can run. Firebase is telemetry-only: degrade and boot without.
+    debugPrint(
+      '[fah] firebase options unavailable, continuing without: $error',
+    );
+    return;
+  }
   final inExtension = Uri.base.scheme == 'chrome-extension';
   if (inExtension || options.apiKey.startsWith('YOUR_')) return;
   try {
